const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let world,room,session,tab='orders',homeTab='create',draft=[],selected,scale=1,pan={x:0,y:0},busy=false,orderDirty=false,toastTimer,polling=false,lastFingerprint='',chatTo='all';
