const pendingInvite=()=>new URLSearchParams(location.hash.slice(1)).get('invite')||'';
async function loadRooms(){const data=await api('/account/rooms');sessions=Object.fromEntries(data.rooms.map(r=>[r.id,r]));}
async function showHome(){await loadRooms();home();const id=new URL(location.href).searchParams.get('room');if(id&&sessions[id])await resume(id);}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',6500);}
const api=request;
const call=async(action,b)=>{const active=session,id=room.id,seat=room.me;const result=await api(`/rooms/${id}/${action}`,{...b,_seat:seat});if(session!==active||room?.me!==seat)throw new Error('Campaign view changed. Reopen the campaign to see the action result.');return result;};
const country=id=>(room?.world||world).countries.find(c=>c.id===id);
