 $('#name-field').classList.toggle('hidden',!['recruit','rename','release'].includes(type));$('#government-field').classList.toggle('hidden',type!=='government');$('#nation-field').classList.toggle('hidden',!['cede','annex','merge','treaty','breakTreaty'].includes(type));
 $('#terms-field').classList.toggle('hidden',type!=='treaty');
 const units=room.world.units.filter(u=>u.country===me().country),oldUnit=$('#unit').value;
 $('#unit').innerHTML=options(units.map(u=>[u.id,`${u.name} · ${room.world.regions.find(r=>r.id===u.province)?.name}`]),oldUnit);if(!units.length)$('#unit').innerHTML='<option value="">No armies</option>';
 const unit=units.find(u=>u.id===$('#unit').value),origin=room.world.regions.find(r=>r.id===unit?.province),old=$('#target').value;
