const project=point=>projectPoint(room?.world||world,point);
function focusNation(id=me().country){const camera=nationCamera(room.world,country(id));scale=camera.scale;pan=camera.pan;transform();}
const regionPath=r=>polygonPath(room?.world||world,r.polygons||[[r.points]]);
function renderMap(){
 const w=room.world,changed=new Set(room.history.at(-1)?.changedProvinces||[]);
 const choice=$('#map-country').value;$('#map-country').innerHTML='<option value="">Find a nation…</option>'+options(w.countries.filter(c=>w.regions.some(r=>r.owner===c.id)).map(c=>[c.id,c.name]).sort((a,b)=>a[1].localeCompare(b[1])),choice);
 $('#map-inner').innerHTML=(w.neutralPolygons?.length?`<path class="neutral-land" d="${polygonPath(w,w.neutralPolygons)}" fill-rule="evenodd"><title>Antarctica · not governed</title></path>`:'')+w.regions.map(r=>`<path class="territory ${r.id===selectedProvince?'selected':''} ${changed.has(r.id)?'map-changed':''}" data-region="${esc(r.id)}" d="${regionPath(r)}" fill-rule="evenodd" fill="${esc(country(r.owner).color)}" style="--territory-fill:${esc(country(r.owner).color)}" tabindex="0" role="button" aria-label="${esc(r.name)}, controlled by ${esc(country(r.owner).name)}"><title>${esc(r.name)} · ${esc(country(r.owner).name)}</title></path>`).join('')+w.countries.filter(c=>w.regions.some(r=>r.owner===c.id)).map(c=>{const p=project(c.label);return `<text class="maplabel" data-map-label="${esc(c.id)}" style="text-anchor:${c.id==='CL'||c.label[0]>155?'end':c.label[0]<-150?'start':'middle'}" x="${p[0]}" y="${p[1]}">${esc(c.name)}</text>`;}).join('');
 const c=country(selected),province=w.regions.find(r=>r.id===selectedProvince);
 $('#map-detail').classList.toggle('hidden',!selectedProvince);
 $('#map-detail').innerHTML=`<button class="quiet small drawer-close" data-action="close-map-detail" aria-label="Close country details">×</button><div class="eyebrow">${c.id===me().country?'Your nation':room.players.some(p=>p.country===c.id)?'Human government':'AI government'}</div><strong>${flag(c.id)}${esc(c.name)}</strong><div class="tiny muted">${province?esc(province.name)+'<br>':''}${esc(c.government)} · ${esc(c.ideology)}<br>${esc(c.leader)}</div><button class="quiet small" data-focus-nation="${esc(c.id)}">Zoom to nation</button>${c.id!==me().country?`<button class="quiet small" data-negotiate="${esc(c.id)}">Open diplomacy →</button>`:''}`;
 transform();
}
function renderDiplomacyTargets(){
 const nearby=new Set(room.nearby||[]),human=id=>room.players.some(p=>p.country===id),others=room.world.countries.filter(c=>c.id!==me().country&&!['merged','annexed'].includes(c.status));
 if(chatTo!=='all'&&!others.some(c=>c.id===chatTo))chatTo='all';
 const groups=[['Nearby AI governments',others.filter(c=>nearby.has(c.id)&&!human(c.id))],['Nearby human governments',others.filter(c=>nearby.has(c.id)&&human(c.id))],['Other governments',others.filter(c=>!nearby.has(c.id))]];
 $('#recipient').innerHTML='<option value="all">World congress · public</option>'+groups.filter(([,cs])=>cs.length).map(([name,cs])=>`<optgroup label="${esc(name)}">${cs.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} · ${human(c.id)?'human':'AI'}</option>`).join('')}</optgroup>`).join('');$('#recipient').value=chatTo;
 $('#nearby-nations').innerHTML=others.filter(c=>nearby.has(c.id)).map(c=>`<button class="small" data-negotiate="${c.id}">${flag(c.id)}${esc(c.name)} <span class="tiny muted">${human(c.id)?'human':'AI'}</span></button>`).join('')||'<p class="tiny muted">No neighboring governments on the current map.</p>';
}
function renderMessages(){$('#diplomacy-status').textContent=chatTo==='all'?'Public conversation with all campaign players.':room.players.some(p=>p.country===chatTo)?'Private conversation with this country’s human player.':'Private AI diplomacy through the host’s Ollama model. Negotiations inform the next shared turn; no changes happen immediately.';const msgs=room.messages.filter(m=>chatTo==='all'?m.to==='all':(m.from===me().country&&m.to===chatTo)||(m.from===chatTo&&m.to===me().country));const box=$('#messages');const atBottom=box.scrollHeight-box.scrollTop-box.clientHeight<40;box.innerHTML=msgs.length?msgs.map(m=>`<div class="message ${m.from===me().country?'mine':''}"><span class="who">${esc(country(m.from)?.name)} · ${esc(m.date)}</span>${esc(m.text)}</div>`).join(''):'<p class="empty">No messages yet. Start a conversation.</p>';if(atBottom)box.scrollTop=box.scrollHeight;}
function transform(){
 const g=$('#map-inner');if(!g)return;const view=mapViewport(room.world);
 g.setAttribute('transform',`translate(${pan.x} ${pan.y}) translate(${view.cx} ${view.cy}) scale(${scale}) translate(${-view.cx} ${-view.cy})`);
 const overview=new Set(['US','CA','MX','BR','AR','CO','PE','CL','SU','CN','JP','IN','IR','SA','AU','NZ','ZA','EG','ET','TH']),mobileOverview=new Set(['US','CA','BR','SU','CN','IN','AU','ZA']);
 const short={MX:'Mexico',AR:'Argentina',CO:'Colombia',PE:'Peru',CN:'China',IN:'India',IR:'Iran',SA:'Arabia',TH:'Siam',AU:'Australia',ZA:'South Africa',EG:'Egypt'};
 const unitPixels=$('#map').getScreenCTM().a,mobile=$('#map').clientWidth<500;
 g.querySelectorAll('[data-map-label]').forEach(label=>{const id=label.dataset.mapLabel;label.style.fontSize=`${Math.max(view.global?3.4:.82,9/unitPixels)/scale}px`;label.textContent=view.global&&scale<2.5?(short[id]||country(id).name):country(id).name;label.style.opacity=view.global&&scale<2.5&&!(mobile?mobileOverview:overview).has(id)?'0':'1';});

}
function mapInteractions(){
 const svg=$('#map');let drag=null,moved=false,pressedRegion=null;const pointers=new Map();let pinch=null;
 const point=e=>{const p=new DOMPoint(e.clientX,e.clientY);return p.matrixTransform(svg.getScreenCTM().inverse());};
 const view=mapViewport(room.world);const zoom=(factor,anchor={x:view.cx,y:view.cy})=>{const next=Math.max(1,Math.min(view.maxZoom,scale*factor)),ratio=next/scale;pan={x:anchor.x-view.cx-(anchor.x-view.cx-pan.x)*ratio,y:anchor.y-view.cy-(anchor.y-view.cy-pan.y)*ratio};scale=next;transform();};
 svg.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY<0?1.12:1/1.12,point(e));},{passive:false});
 svg.onpointerdown=e=>{if(e.button!==0)return;pressedRegion=e.target.closest('[data-region]');pointers.set(e.pointerId,point(e));svg.setPointerCapture(e.pointerId);if(pointers.size===2){const [a,b]=[...pointers.values()];pinch={distance:Math.hypot(a.x-b.x,a.y-b.y)};moved=true;drag=null;}else{drag={point:point(e),pan:{...pan}};moved=false;}};
 svg.onpointermove=e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,point(e));if(pointers.size===2){const [a,b]=[...pointers.values()],distance=Math.hypot(a.x-b.x,a.y-b.y);if(pinch?.distance)zoom(distance/pinch.distance,{x:(a.x+b.x)/2,y:(a.y+b.y)/2});pinch={distance};return;}if(!drag)return;const p=point(e),dx=p.x-drag.point.x,dy=p.y-drag.point.y;if(Math.hypot(dx,dy)*svg.getScreenCTM().a>4){moved=true;pan={x:drag.pan.x+dx,y:drag.pan.y+dy};transform();}};
 const stop=e=>{pointers.delete(e.pointerId);drag=null;pinch=null;};svg.onpointerup=stop;svg.onpointercancel=stop;
 const select=target=>{const region=target?.closest('[data-region]');if(region){selectedProvince=region.dataset.region;selected=room.world.regions.find(r=>r.id===selectedProvince).owner;renderMap();}};
 svg.onclick=e=>{if(!moved)select(pressedRegion||e.target);pressedRegion=null;};svg.onkeydown=e=>{if(['Enter',' '].includes(e.key)&&e.target.dataset.region){e.preventDefault();select(e.target);}};
}
function switchTab(t){
 tab=t;if(t==='orders')actionsOpen=true;
 document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab==='orders'?actionsOpen:b.dataset.tab===t);b.setAttribute('aria-selected',b.dataset.tab===t);});
 $('#orders-panel').classList.toggle('hidden',!actionsOpen);for(const n of ['diplomacy','advisor'])$('#'+n+'-panel').classList.toggle('hidden',n!==t);
 $('.shell').classList.toggle('actions-open',actionsOpen);$('.shell').classList.toggle('secondary-open',t!=='orders');
}

async function saveOrders(){room=await call('orders',{orders:draft});orderDirty=false;lastFingerprint='';render();}
async function refresh(){if(!session||polling)return;polling=true;try{const requestedSession=session;const next=await api('/rooms/'+requestedSession.id);if(session!==requestedSession)return;if(room&&(next.round!==room.round||next.epoch!==room.epoch||next.me!==room.me)){draft=structuredClone(next.players.find(p=>p.id===next.me).orders);orderDirty=false;if(next.me!==room.me){selected=next.players.find(p=>p.id===next.me).country;selectedProvince=null;chatTo='all';}}room=next;$('#connection')?.classList.add('hidden');render();}catch(e){if(e.status===401){loginScreen();}else if(e.status===403){session=null;room=null;await showHome();toast(e.message);}else $('#connection')?.classList.remove('hidden');}finally{polling=false;}}
function showDialog(html){const d=$('#settings');d.innerHTML=html;d.showModal();}
function scenarioEditor(){
 if($('#settings').open)$('#settings').close();
 showDialog(`<h2>Starting-world editor</h2><p>Edit or paste an original scenario JSON. This replaces the starting world and clears orders and chats. Every seated human nation must remain present with land. Available only in turn 1 with everyone unready.</p><form id="scenario-form"><label for="scenario-json">Scenario JSON</label><textarea id="scenario-json" class="scenario-json" spellcheck="false">${esc(JSON.stringify(room.world,null,2))}</textarea><div id="scenario-error" class="error hidden" role="alert"></div><button class="primary wide">Replace starting world</button><button type="button" data-action="close-dialog">Cancel</button></form>`);
 $('#scenario-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const source=JSON.parse($('#scenario-json').value),world=source.world||source;room=await call('scenario',{world});$('#settings').close();mountGame();toast('Starting world updated.');}catch(e){$('#scenario-error').textContent=e.message;$('#scenario-error').classList.remove('hidden');}finally{button.disabled=false;}};
}
function timeline(){if($('#settings').open)$('#settings').close();showDialog(`<h2>Timeline checkpoints</h2><p>Rewind discards later world history, chats, advisor exchanges and all current orders. Accounts and campaign seats remain. Up to 20 pre-turn checkpoints are kept.</p>${(room.config.checkpoints||[]).map(p=>`<button class="wide" data-rewind="${p.round}">Rewind to turn ${p.round} · ${esc(p.date)}</button>`).join('')||'<p>No completed turns yet.</p>'}<button data-action="close-dialog">Cancel</button>`);}
function settings(){const c=room.config;showDialog(`<div class="row spread"><h2>${isHost()?'Host settings':'Your session'}</h2><button class="quiet" data-action="close-dialog">×</button></div><p>Campaign ${esc(room.id)} · ${esc(room.name)}</p><div class="row">${isHost()?'<button class="small" data-action="export">Export world & history</button>':''}</div><p>Campaign permissions are tied to your signed-in account.</p>${isHost()?'<button data-action="timer-settings">Configure live turn timer</button><button data-action="scenario-editor">Starting-world editor</button><button data-action="timeline">Timeline checkpoints</button>':''}${isHost()?`<form id="config-form"><div class="section-line"></div><label for="map-mode">Game style</label><select id="map-mode">${options([["wild","Wild map · AI redraws borders"],["strategy","Strategy · national orders"]],room.world.mapMode)}</select><label class="protect-label"><input type="checkbox" id="protect-players" ${room.world.protectPlayers?"checked":""}> Map director leaves human nations at least one province</label><p class="tiny muted">Wild mode requires a real ownership change every AI turn. New states, collapses, unions and border transfers apply directly to the map. Ordinary military losses are separate.</p><label for="ai-mode">Simulation mode</label><select id="ai-mode">${options([['ollama','Ollama · AI world simulation'],['demo','Demo · deterministic rules only']],c.mode)}</select><label for="endpoint">Ollama base URL</label><select id="endpoint">${options(c.allowedEndpoints.map(e=>[e,e]),c.endpoint)}</select><p>Only server-approved AI endpoints are available. The server owner configures the allowlist; campaign hosts cannot add URLs.</p><label for="model">Model name</label><input id="model" value="${esc(c.model)}" list="model-list" placeholder="Exact name from ollama list"><datalist id="model-list"></datalist><button class="small" style="margin-top:8px" type="button" data-action="models">Save & discover installed models</button><p class="tiny muted">AI memory: ${c.aiProfile.contextLength.toLocaleString()} context · ${c.aiProfile.concurrency} generation(s) · automatic history compaction. Large turns use sequential policy batches within the same context limit. Full orders and archives stay saved.</p><label for="months">Time per turn</label><select id="months">${options([[1,'1 month'],[3,'3 months'],[6,'6 months']],room.months)}</select><label for="premise">Simulation rules & world premise</label><textarea id="premise" maxlength="10000">${esc(room.world.premise)}</textarea><details class="prompt-editor"><summary>AI system prompts · view & edit</summary><p class="tiny muted">Saved per campaign. The application contract is appended to each prompt and server validation remains enforced. Diplomacy accepts {{countryName}} and {{countryId}} placeholders.</p>${['turn','diplomacy','advisor'].map(k=>`<label for="prompt-${k}">${esc(k)} prompt</label><textarea id="prompt-${k}" maxlength="6000">${esc(c.prompts[k])}</textarea><details><summary class="tiny">Application contract</summary><pre class="prompt-contract">${esc(c.promptContracts[k])}</pre></details>`).join('')}<button type="button" class="small" data-action="reset-prompts">Reset prompt fields to defaults</button></details><div id="model-status" class="tiny muted" style="margin-top:10px"></div><button class="primary wide" style="margin-top:20px">Save settings</button></form>`:''}`);if(isHost())$('#config-form').onsubmit=async e=>{e.preventDefault();try{await saveConfig();toast('Host settings saved.');$('#settings').close();}catch(e){toast(e.message);}};}
