document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b||b.disabled||busy)return;
 if(b.dataset.home){switchHome(b.dataset.home);return;}
 if(b.dataset.resume){await resume(b.dataset.resume);return;}
 if(b.dataset.focusNation){focusNation(b.dataset.focusNation);return;}
 if(b.dataset.tab){switchTab(b.dataset.tab);return;}
 if(b.dataset.negotiate){chatTo=b.dataset.negotiate;$('#recipient').value=chatTo;switchTab('diplomacy');renderMessages();$('#recipient').scrollIntoView({behavior:'smooth',block:'nearest'});return;}
 if(b.dataset.removeOrder!==undefined){if(busy)return;if(ordersLocked()||me().ready){toast('Saved actions are locked.');return;}busy=true;draft.splice(Number(b.dataset.removeOrder),1);orderDirty=true;renderOrders();try{await saveOrders();}catch(error){toast(error.message);}finally{busy=false;render();}return;}
 try{
 if(b.dataset.rewind){if(!confirm('Discard all later history and dialogue and return to this checkpoint?'))return;room=await call('rewind',{round:Number(b.dataset.rewind)});$('#settings').close();mountGame();return;}
 if(b.dataset.removePlayer){showDialog(`<h2>Remove this government?</h2><p>The player will lose access to this campaign. Their country becomes AI-controlled. Their private orders are discarded.</p><button class="primary" id="confirm-remove">Remove player</button> <button data-action="close-dialog">Cancel</button>`);$('#confirm-remove').onclick=async()=>{try{room=await call('remove',{playerId:b.dataset.removePlayer});$('#settings').close();lastFingerprint='';render();}catch(e){toast(e.message);}};return;}
 const action=b.dataset.action;
 if(action==='collapse-actions'){actionsOpen=false;$('#orders-panel').classList.add('hidden');$('.shell').classList.remove('actions-open');document.querySelector('[data-tab="orders"]').classList.remove('active');return;}
 if(action==='close-secondary'){switchTab('orders');return;}
 if(action==='structured-orders'){switchTab('orders');$('.shell').classList.toggle('advanced-open');$('.structured-actions').open=$('.shell').classList.contains('advanced-open');$('.game-menu').open=false;return;}
 if(action==='toggle-campaign'||action==='toggle-history'){const id=action==='toggle-campaign'?'campaign-drawer':'history-drawer';const panel=$('#'+id),open=panel.classList.toggle('open');document.querySelectorAll(`[data-action="${action}"]`).forEach(b=>b.setAttribute('aria-expanded',String(open)));return;}
 if(action==='scenario-editor'){scenarioEditor();return;}
 if(action==='timeline'){timeline();return;}
 if(action==='suggestions'){b.disabled=true;try{await call('suggestions',{});switchTab('advisor');await refresh();}finally{b.disabled=false;}return;}
 if(action==='timer-settings'){timerSettings();return;}
 if(['timer-pause','timer-resume','timer-extend','timer-disable'].includes(action)){busy=true;room=await call('timer',{command:action==='timer-disable'?'configure':action.slice(6),seconds:action==='timer-disable'?0:60,round:room.round});if($('#settings').open)$('#settings').close();lastFingerprint='';return;}
 if(action==='load-nations'){await loadNations();return;}
 if(action==='reset-prompts'){for(const k of ['turn','diplomacy','advisor'])$('#prompt-'+k).value=room.config.promptDefaults[k];return;}
 if(action==='exit'){history.replaceState(null,'','/');await showHome();return;}
 if(action==='admin'){await adminScreen();return;}
 if(action==='close-dialog'){$('#settings').close();return;}
 if(action==='settings'){settings();return;}
 if(action==='export'){download(`historia-${room.id}-world.json`,await api(`/rooms/${room.id}/export`));return;}
 if(action==='invite'){showDialog(`<h2>Invite a government.</h2><p>Players need their own account and a campaign invitation. Generate one reusable link for multiple players, valid for seven days. Generating another link revokes the previous campaign invitation.</p><button class="primary" data-action="generate-invite">Generate join invitation</button> <button data-action="close-dialog">Close</button>`);return;}
 if(action==='generate-invite'){const data=await call('invite',{});inviteLink=location.origin+'/?room='+room.id+'#invite='+data.invite;showDialog(`<h2>Campaign invitation</h2><p>Share this link with multiple friends. It expires in seven days, or when replaced. Anyone without an account will be prompted to register before choosing a nation.</p><div class="instructions" style="overflow-wrap:anywhere">${esc(inviteLink)}</div><button class="primary" style="margin-top:15px" data-action="copy-invite">Copy join link</button> <button data-action="close-dialog">Done</button>`);return;}
 if(action==='copy-invite'){try{await navigator.clipboard.writeText(inviteLink);toast('Join link copied.');}catch{toast('Select and copy the join link shown above.');}return;}
 if(action==='rules'){showDialog(`<h2>The next chapter is yours.</h2><p>Choose your country and submit up to three actions. Each action saves automatically. Negotiate or ask your advisor for help. Other players mark ready; the host uses Jump Forward to save, ready and advance in one click.</p><p>Actions are attempts. The simulation considers resources, logistics and other governments before resolving them. Your economic and military details are managed internally.</p><p>Use Game menu → Structured orders for direct army, government and treaty orders. Army movement requires adjacent regions; treaties and unification require reciprocal consent. Diplomacy takes effect on the next turn.</p><p>The world map uses interwar Historical Basemaps data. Smaller states and territories are grouped with larger playable governments. Borders and groupings are approximate; regions are gameplay sectors. Antarctica is shown as neutral land. Use Find a nation or My nation to zoom in, and World to return to the overview.</p><button class="primary" data-action="close-dialog">Back to the world</button>`);return;}
 if(action==='archives'){showDialog(`<h2>Revealed orders</h2><p>Orders become public after their turn is resolved.</p>${room.history.slice().reverse().map(h=>`<h3>Turn ${h.round} · ${esc(h.date)}</h3>${h.orders.map(p=>`<p><strong>${esc(p.name)} · ${esc(country(p.country).name)}</strong><br>${p.orders.length?p.orders.map(o=>esc(o.type+(o.text?': '+o.text:o.target?': '+o.target:''))).join('<br>'):'No orders.'}</p>`).join('')}`).join('')||'<p>No turns resolved yet.</p>'}<button data-action="close-dialog">Close</button>`);return;}
 if(action==='models'){b.disabled=true;$('#model-status').textContent='Connecting to Ollama…';try{await saveConfig();const d=await call('models',{});$('#model-list').innerHTML=d.models.map(m=>`<option value="${esc(m)}">`).join('');$('#model-status').textContent=d.models.length?'Connected. Available: '+d.models.join(', '):'Connected, but no models installed. Pull one with Ollama first.';if(!$('#model').value&&d.models.length)$('#model').value=d.models[0];}catch(e){$('#model-status').textContent=e.message;}finally{b.disabled=false;}return;}
 if(action==='add-order'){if(busy)return;busy=true;
  if(ordersLocked()||me().ready)throw new Error('Saved actions are locked.');
  if(draft.length>=3)throw new Error('You can queue up to three orders.');
  const type=$('#order-type').value,o={type};
  if(type==='policy')o.text=$('#policy').value.trim();
  if(['move','attack'].includes(type))o.unit=$('#unit').value;
  if(['move','attack','recruit','release','cede'].includes(type))o.target=$('#target').value;
  if(['recruit','release','rename'].includes(type))o.name=$('#order-name').value.trim();
  if(['cede','annex','merge','treaty','breakTreaty'].includes(type))o.targetCountry=$('#target-nation').value;
  if(type==='treaty')o.terms=$('#treaty-terms').value;
  if(type==='government'){o.government=$('#government-type').value;o.ideology=$('#ideology').value;o.leader=$('#leader').value.trim();}
  if(type==='policy'&&!o.text)throw new Error('Describe your policy.');
  draft.push(o);orderDirty=true;$('#policy').value='';renderOrders();await saveOrders();return;
 }
 if(action==='save-orders'){await saveOrders();toast('Actions saved privately.');return;}
 if(action==='ready'){busy=true;if(orderDirty)await saveOrders();room=await call('ready',{ready:!me().ready});lastFingerprint='';return;}
 if(action==='advance'){busy=true;b.disabled=true;b.textContent='Simulating…';if(orderDirty)await saveOrders();if(!deadlinePassed()&&!me().ready){room=await call('ready',{ready:true});lastFingerprint='';}const request=call('advance',{});await refresh();const next=await request;if(room.round!==next.round||room.epoch!==next.epoch){draft=structuredClone(next.players.find(p=>p.id===next.me).orders);orderDirty=false;if(next.me!==room.me){selected=next.players.find(p=>p.id===next.me).country;selectedProvince=null;chatTo='all';}}room=next;lastFingerprint='';return;}
 if(action==='close-map-detail'){selectedProvince=null;renderMap();return;}
 if(action==='map-focus'){selected=me().country;selectedProvince=null;$('#map-country').value=selected;focusNation();renderMap();return;}
 if(action==='zoom-in'){scale=Math.min(mapViewport(room.world).maxZoom,scale*1.25);transform();}
 if(action==='zoom-out'){scale=Math.max(1,scale/1.25);transform();}
 if(action==='map-reset'){scale=1;pan={x:0,y:0};selectedProvince=null;$('#map-country').value='';renderMap();}
 }catch(e){toast(e.message);await refresh();}finally{busy=false;if(room){lastFingerprint='';render();}}
});
async function boot(){try{world=await api('/scenario');if(await initAccounts(showHome,()=>{session=null;room=null;}))await showHome();setInterval(refresh,1800);setInterval(renderTimer,250);}catch(e){$('#app').innerHTML='<main style="padding:40px"><h1>Cannot reach the game server.</h1><p>Start the server and reload this page. Check the terminal for deployment errors.</p></main>';}}
boot();
